// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        bool ok1;
        vm.prank(actor);
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(actor);
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok1 || ok2);
    }
}
